// 1. Configuración de Horario (15 min)
const businessHours = ["09:00", "09:15", "09:30", "09:45", "10:00", "10:15", "10:30", "10:45", "11:00", "11:15", "11:30", "11:45", "12:00", "12:15", "12:30", "12:45", "13:00", "13:15", "13:30", "13:45", "14:00", "14:15", "14:30", "14:45", "15:00", "15:15", "15:30", "15:45", "16:00", "16:15", "16:30", "16:45", "17:00", "17:15", "17:30", "17:45", "18:00", "18:15", "18:30", "18:45", "19:00", "19:15", "19:30", "19:45"];
const diasA_Escanear = 2;
const OFFSET = "-03:00"; // Desplazamiento de Argentina

// 2. MAPPING
const calendarConfig = [
  { skyiaId: 10, node: "Get Events GHL meso", calId: "LzQBDcqDSopp37434OTm" },
  { skyiaId: 7, node: "Get Events GHL prp", calId: "Nn2PyACs0OBYSrQ5bFzu" },
  { skyiaId: 5, node: "Get Events GHL clientes", calId: "47N4WxTdTAOqHLmQd54i" },
  { skyiaId: 5,  node: "Get Events GHL revisaciones", calId: "fGnEFWqMyFh0VIPV1biz" },
  { skyiaId: 3,  node: "Get Events GHL controles", calId: "MEpJfFMuZXbtMgK8DbCy" },
  { skyiaId: 13,  node: "Get Events GHL dermo", calId: "wWpl7nHjIzE2wbndE8pE" }
];

const skyiaFree = $("Get Free Slots CRM Capilea").all();
const ghlDataByNode = {};

calendarConfig.forEach(conf => {
  try {
    const response = $(conf.node).first().json;
    ghlDataByNode[conf.node] = response.events || [];
  } catch (e) {
    ghlDataByNode[conf.node] = [];
  }
});

const results = [];
const hoy = new Date();

const getNext15Min = (hora) => {
  let [hh, mm] = hora.split(':').map(Number);
  mm += 15;
  if (mm === 60) { hh += 1; mm = 0; }
  return `${String(hh).padStart(2, '0')}:${String(mm).padStart(2, '0')}`;
};

for (let i = 0; i < diasA_Escanear; i++) {
  const fechaEvaluar = new Date(hoy);
  fechaEvaluar.setDate(hoy.getDate() + i);
  const yyyy = fechaEvaluar.getFullYear();
  const mm = String(fechaEvaluar.getMonth() + 1).padStart(2, '0');
  const dd = String(fechaEvaluar.getDate()).padStart(2, '0');
  const fechaISO = `${yyyy}-${mm}-${dd}`;

  const slotsSkyiaDeEsteDia = skyiaFree.filter(item => {
    const f = item.json.FECHA && item.json.FECHA[0] ? item.json.FECHA[0].split('T')[0] : null;
    return f === fechaISO;
  });

  if (slotsSkyiaDeEsteDia.length === 0) continue;

  calendarConfig.forEach(conf => {
    const currentSkyiaId = conf.skyiaId;
    const currentGhlEvents = ghlDataByNode[conf.node];

    businessHours.forEach(hora => {
      const horaFinSlot = getNext15Min(hora);

      // CAMBIO AQUÍ: Añadimos el OFFSET para comparar timestamps idénticos
      const slotStart = new Date(`${fechaISO}T${hora}:00${OFFSET}`).getTime();
      const slotEnd = new Date(`${fechaISO}T${horaFinSlot}:00${OFFSET}`).getTime();

      const estaLibreEnSkyia = slotsSkyiaDeEsteDia.some(slot => 
        slot.json.HORA === hora && Number(slot.json.IDPROFESIONAL) === Number(currentSkyiaId)
      );

      const cubiertoPorGHL = currentGhlEvents.some(event => {
        const eventStart = new Date(event.startTime).getTime();
        const eventEnd = new Date(event.endTime).getTime();
        // Verificamos si hay solapamiento exacto
        return eventStart <= slotStart && eventEnd >= slotEnd;
      });

      if (!estaLibreEnSkyia && !cubiertoPorGHL) {
        results.push({
          json: {
            fecha: fechaISO,
            hora: hora,
            calendarId: conf.calId,
            skyiaId: currentSkyiaId,
            startDateTime: `${fechaISO}T${hora}:00${OFFSET}`,
            endDateTime: `${fechaISO}T${horaFinSlot}:00${OFFSET}`,
            debug: `Skyia ${currentSkyiaId} Ocupado | GHL ${conf.calId} Libre`
          }
        });
      }
    });
  });
}

const finalResults = [];
const seen = new Set();
results.forEach(item => {
  const key = `${item.json.calendarId}_${item.json.startDateTime}`;
  if (!seen.has(key)) {
    seen.add(key);
    finalResults.push(item);
  }
});

return finalResults;

