// 1. Configuración de Mapeo SkyiaId -> Categoría Profesional
const idToProf = {
  "1": "AUSENTES", "2": "CANCELADOS", "3": "CONTROLES",
  "5": "REVISACIONES", "7": "PLASMA", "10": "MESOTERAPIA", "13": "DERMO"
};

// 2. RECUPERACIÓN DE DATOS
const skyiaEvents = $("Get_Skyia_Events_Details").all().map(item => item.json)
                    .filter(event => event.idTurno); 

const syncBlocks = $("Comparador_bloques").all(); 
const finalSync = [];
const processedBlocks = new Set(); 
const processedAppointments = new Set(); 
const normalizeDate = (d) => d ? d.split('T')[0] : null;

// --- PASO 1: Identificar y Consolidar TODAS las Citas Reales ---
syncBlocks.forEach(block => {
  const b = block.json;
  const targetProf = idToProf[b.skyiaId.toString()];

  // CAMBIO CLAVE: Usamos .filter() para traer todas las citas del slot
  const matchingEvents = skyiaEvents.filter(event => {
    const sameDate = normalizeDate(event.fecha) === b.fecha;
    const sameProf = event.profesional === targetProf;
    const isWithinRange = b.hora >= event.horaInicio && b.hora < event.horaFin;
    return sameDate && sameProf && isWithinRange;
  });

  if (matchingEvents.length > 0) {
    matchingEvents.forEach(matchingEvent => {
      const appointmentKey = `${b.calendarId}_${matchingEvent.idTurno}`;

      // Si la cita no ha sido procesada (para casos de citas de 30/60 min)
      if (!processedAppointments.has(appointmentKey)) {
        let title = "Ocupado Skyia";
        // Lista extendida de IDs para mostrar título completo
        const idsConDetalle = ["10", "5", "7", "13", "1", "2", "3"];

        if (idsConDetalle.includes(b.skyiaId.toString())) {
          title = `${matchingEvent.paciente} - ${matchingEvent.producto}`;
        }

        finalSync.push({
          json: {
            fecha: b.fecha,
            startTime: `${b.fecha}T${matchingEvent.horaInicio}:00`,
            endTime: `${b.fecha}T${matchingEvent.horaFin}:00`,
            calendarId: b.calendarId,
            title: title,
            nombreCompleto: matchingEvent.paciente,
            email: matchingEvent.mail || `sync_${matchingEvent.idPaciente}@skyia.com`,
            telefono: matchingEvent.telefono || "",
            idTurno: matchingEvent.idTurno,
            tipo: "Cita Detallada"
          }
        });
        processedAppointments.add(appointmentKey);
      }
    });
    // Marcamos el bloque como procesado para que no genere un "Ocupado Skyia" genérico
    processedBlocks.add(`${b.calendarId}_${b.startDateTime}`);
  }
});

// --- PASO 2: Bloqueos Manuales o Anónimos ---
syncBlocks.forEach(block => {
  const b = block.json;
  const blockKey = `${b.calendarId}_${b.startDateTime}`;

  if (!processedBlocks.has(blockKey)) {
    finalSync.push({
      json: {
        fecha: b.fecha,
        startTime: b.startDateTime,
        endTime: b.endDateTime,
        calendarId: b.calendarId,
        title: "Ocupado Skyia",
        tipo: "Bloqueo Manual/Interno"
      }
    });
  }
});

return finalSync;

