  { skyiaId: 7, node: "Get Events GHL prp", calId: "Nn2PyACs0OBYSrQ5bFzu" },
  { skyiaId: 5, node: "Get Events GHL clientes", calId: "47N4WxTdTAOqHLmQd54i" },
  { skyiaId: 5,  node: "Get Events GHL revisaciones", calId: "fGnEFWqMyFh0VIPV1biz" },
  { skyiaId: 3,  node: "Get Events GHL controles", calId: "MEpJfFMuZXbtMgK8DbCy" },
  { skyiaId: 13,  node: "Get Events GHL dermo", calId: "wWpl7nHjIzE2wbndE8pE" }
];

const businessHours = ["09:00", "09:15", "09:30", "09:45", "10:00", "10:15", "10:30", "10:45", "11:00", "11:15", "11:30", "11:45", "12:00", "12:15", "12:30", "12:45", "13:00", "13:15", "13:30", "13:45", "14:00", "14:15", "14:30", "14:45", "15:00", "15:15", "15:30", "15:45", "16:00", "16:15", "16:30", "16:45", "17:00", "17:15", "17:30", "17:45", "18:00", "18:15", "18:30", "18:45", "19:00", "19:15", "19:30", "19:45"];
const OFFSET = "-03:00";

// 2. RECUPERACIÓN DE DATOS
const skyiaFree = $("Get Free Slots CRM Capilea").all();
// Consolidamos todos los detalles de citas de los nodos "Get Info Skyia"
const skyiaDetails = $("Get_Skyia_Events_Details").all().map(i => i.json).filter(e => e.idTurno);

const ghlDataByNode = {};
calendarConfig.forEach(conf => {
  try { ghlDataByNode[conf.node] = $(conf.node).first().json.events || []; } 
  catch (e) { ghlDataByNode[conf.node] = []; }
});

const finalSync = []; // AHORA SÍ: Definido correctamente
const diasA_Escanear = 5;
const hoy = new Date();

// 3. PROCESAMIENTO
for (let i = 0; i < diasA_Escanear; i++) {
  const fechaEvaluar = new Date(hoy);
  fechaEvaluar.setDate(hoy.getDate() + i);
  const yyyy = fechaEvaluar.getFullYear();
  const mm = String(fechaEvaluar.getMonth() + 1).padStart(2, '0');
  const dd = String(fechaEvaluar.getDate()).padStart(2, '0');
  const fechaISO = `${yyyy}-${mm}-${dd}`;

  const slotsSkyiaDeEsteDia = skyiaFree.filter(item => {
    const f = item.json.FECHA && item.json.FECHA[0] ? item.json.FECHA[0].split('T')[0] : null;
    return f === fechaISO;
  });

  calendarConfig.forEach(conf => {
